const items = $input.all();
const data = $('Load Queued Messages from Queue Sheet');
const sheet_id = data.item.json.sheet_id ?? '';
// Referenced directly from the queue read (not the splitInBatches loop node)
// and coerced to '' instead of left undefined -- when this evaluated to
// undefined, the resulting json object never had a row_number KEY at all
// (JS/JSON serialization drops undefined-valued keys entirely), and since
// the sheet's header already reserves a column for it, autoMapInputData
// wrote fromEmail's value into the row_number cell instead and shifted
// every field after it one column left. Same fix as the Gmail processor.
const row_number = data.item.json.row_number ?? '';
// logged-in mailbox email
// the mailbox this message was fetched from (queue column by_mail), so SENT / RECEIVED is
// judged against that mailbox's own address; unknown / older rows ('outlook') = the original mailbox
const MAILBOX_ADDRESS = {
  outlook: 'jack@marblebee.com',
  outlook_jack: 'jack@marblebee.com',
  outlook_mia: 'mia@marblebee.com',
  outlook_eve: 'eve@marblebee.com',
  outlook_yolanda: 'yolanda@marblebee.com'
};
const byMail = String(data.item.json.by_mail || 'outlook').trim().toLowerCase();
const MY_EMAIL = (MAILBOX_ADDRESS[byMail] || MAILBOX_ADDRESS.outlook).toLowerCase();

/**
 * Cut message at polite sign-offs like "Kind regards,"
 */
function cutAtKindRegards(text = '') {
  const match = text.match(
    /\b(Kind regards|Best regards|Regards|Warm regards),\b/i
  );
  return match ? text.slice(0, match.index).trim() : text.trim();
}

/**
 * Extract latest message from Outlook/Gmail HTML body
 */
function extractLatestMessageFromHtml(html = '') {
  if (!html) return '';

  // Remove scripts & styles
  html = html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '');

  // Cut at known reply/forward separators (earliest match wins)
  const cutPatterns = [
    /<hr[\s\S]*?>/i,
    /<div[^>]+id=["']divRplyFwdMsg["'][\s\S]*?>/i,
    /<div[^>]+class=["'][^"']*gmail_quote[^"']*["'][\s\S]*?>/i,
    /\nOn\s+(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s+[A-Za-z]{3}\s+\d{1,2},\s+\d{4},/i
  ];

  for (const pattern of cutPatterns) {
    const match = html.match(pattern);
    if (match) {
      html = html.slice(0, match.index);
    }
  }

  // Strip remaining HTML -> plain text
  return html
    .replace(/<\/?[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function cutAtReplyDate(text = '') {
  const replyRegex =
    /\nOn\s+(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s+[A-Za-z]{3}\s+\d{1,2},\s+\d{4},\s+\d{1,2}:\d{2}\s*(AM|PM)/i;

  const match = text.match(replyRegex);
  return match ? text.slice(0, match.index).trim() : text.trim();
}

/**
 * Strip HTML safely
 */
function stripHtml(html = '') {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[^>]+(>|$)/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Cut text at first occurrence of:
 *  - 5 or more underscores
 *  - "Get Outlook for "
 * whichever comes first
 */
function cutAtSeparator(text = '') {
  const match = text.match(/_{5,}|Get Outlook for /i);
  return match ? text.slice(0, match.index).trim() : text.trim();
}

return items.map((item, index) => {
  const msg = item.json;

  // sender
  const fromEmail =
    msg.from?.emailAddress?.address || null;
  let fromName =
    msg.from?.emailAddress?.name || null;

  // receivers -- joined into a plain comma-separated string, matching the
  // Gmail processor's convention for this shared sheet (this used to be a
  // raw array, which stringified into the cell as e.g. ["a@b.com"] instead
  // of a clean address).
  const toRecipientsArr = msg.toRecipients || [];
  const toEmail =
    toRecipientsArr.map(r => r.emailAddress?.address).filter(Boolean).join(', ') || null;
  const toName =
    toRecipientsArr.map(r => r.emailAddress?.name).filter(Boolean).join(', ') || null;

  // sent or received -- uppercase to match the Gmail processor's convention;
  // a client's conversation sheet interleaves both providers, so the two
  // must agree on casing.
  // SENT = written by our side: the mailbox owner, OR any other Marblebee address (a colleague
  // writing to the client with this mailbox in copy, or a shared company Gmail account).
  const ownSender = fromEmail?.toLowerCase() === MY_EMAIL || /marblebee/i.test(fromEmail || '');
  const direction = ownSender ? 'SENT' : 'RECEIVED';

  // body (HTML -> text)
let message = '';

if (msg.body?.contentType === 'html') {
  message = extractLatestMessageFromHtml(msg.body.content);
} else {
  message = stripHtml(msg.body?.content || '');
}

// Remove signatures / Outlook footer
message = cutAtSeparator(message);

// Remove quoted reply thread
message = cutAtReplyDate(message);

// Remove content after "Kind regards,"
message = cutAtKindRegards(message);

// Invisible padding some senders (Etsy, newsletters) put at the top of their HTML mails: the HTML code for a
// zero-width space (&#65279; and similar) and zero-width characters. They were copied into the sheet as
// hundreds of meaningless '&#65279;' strings, so they are removed from every message.
message = message
  .replace(/&#(65279|8203|8204|8205|847);?|&zwnj;|&nbsp;/gi, ' ')
  .replace(/[\u200b-\u200f\u2060\ufeff\u034f]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Etsy conversation notices ('Etsy Conversation with <name>', sent by no-reply@account.etsy.com): the e-mail only says
// that the buyer wrote and has a 'View message' button -- the buyer's own text and photos exist only on Etsy and are
// NOT in the e-mail. Instead of Etsy's template text (headline, menu, footer) log a clean one-line note that carries the
// full link of the 'View message' button exactly as it is in the e-mail (it opens the Etsy Messages page of the logged-in
// Etsy account; there is no direct link to the chat). Staff may overwrite this cell with the real text (the duplicate
// check never looks at the message text).
if (/@account\.etsy\.com$/i.test(fromEmail || '') && /Etsy Conversation with/i.test(msg.subject || '')) {
  const buyer = String(msg.subject).replace(/^(\s*re:\s*)*Etsy Conversation with\s*/i, '').trim();
  const html = (msg.body && msg.body.content) || '';
  const linkMatch = html.match(/<a\b[^>]*href=["']([^"']+)["'][^>]*>(?:(?!<\/a>)[\s\S])*?View message/i);
  const link = linkMatch ? linkMatch[1].replace(/&amp;/g, '&') : '';
  message = link
    ? `${buyer} sent a message on Etsy. The text of the message is only on Etsy, open it here: ${link}`
    : `${buyer} sent a message on Etsy. The text is only on Etsy: open https://www.etsy.com/messages and search for "${buyer}".`;
  fromName = buyer + ' (Etsy)';
}


  return {
    json: {
      id: msg.id ?? '',
      sheet_id,
      row_number,
      message,
      fromEmail,
      fromName,
      toEmail,
      toName,
      direction,
      timestamp:
        msg.sentDateTime || msg.receivedDateTime,
      subject: msg.subject || null,
      hasAttachments: msg.hasAttachments || false
    },

    binary: $input.all()[index]?.binary || {}
  };
});

// Each conversation sheet is created via the Sheets API with an explicit
// sheets[] array and no sheetId specified -- per Google's own docs, an
// unspecified sheetId is RANDOMLY GENERATED, not 0, and the tab name itself
// is also inconsistent across sheets ('sheet1' vs 'Sheet1'). Neither a
// hardcoded name nor a hardcoded gid can address it. Look up this specific
// document's actual (single) tab name at runtime and reference it by name
// from here on -- same fix as the Gmail processor.
const original = $('Normalize | Extract Message Metadata').item;
const tabName = $json.sheets?.[0]?.properties?.title;
if (!tabName) {
  throw new Error(`Could not resolve the conversation sheet's tab name for sheet_id ${original.json.sheet_id}`);
}
return [{
  json: { ...original.json, tabName },
  binary: original.binary
}];

// Already logged? The 'Sheets | Find Existing Message Row' step above reads the WHOLE conversation tab (it used to look up only the
// columns fromEmail / toEmail / subject, which the oldest rows do not have: rows written in the older layout keep the sender in
// 'senderEmail' and the recipients in 'receiverEmails', so a copy of such a message from another mailbox was never recognised and
// was logged a second time). A message counts as already logged when ANY row has the same moment (epoch seconds, so Gmail's
// '...56.000Z' and Outlook's '...56Z' match), the same subject (re:/fw: prefixes and spacing ignored) and the same sender
// (fromEmail OR senderEmail; a row with no sender at all matches on moment + subject).
// If the sheet cannot be read this STOPS with an error instead of logging the message (a failed read must never create a duplicate):
// run the workflow again, rows already processed are skipped.
const secs = (t) => { const d = new Date(String(t == null ? '' : t).trim()); return isNaN(d.getTime()) ? null : Math.floor(d.getTime() / 1000); };
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/\s+/g, ' ').trim();
const subj = (s) => { let x = norm(s), prev; do { prev = x; x = x.replace(/^(re|fw|fwd|aw|wg|sv|vs|rv|tr)\s*:\s*/, '').trim(); } while (x !== prev); return x; };
const addr = (s) => { const m = String(s == null ? '' : s).match(/[\w.+'\-]+@[\w.\-]+\.[a-z]{2,}/i); return m ? m[0].toLowerCase() : ''; };
const original = $('Extract Tab Name').item;
const mine = secs(original.json.timestamp);
const mySubject = subj(original.json.subject);
const mySender = addr(original.json.fromEmail);
const res = $input.first().json || {};
if (res.error) throw new Error('Could not read the conversation sheet to check for duplicates (' + JSON.stringify(res.error).slice(0, 200) + '). Nothing was logged for this message; run the workflow again.');
const values = Array.isArray(res.values) ? res.values : [];
let found = false;
if (mine !== null && values.length > 1) {
  const H = values[0].map(h => String(h == null ? '' : h).trim());
  const iTs = H.indexOf('timestamp'), iSub = H.indexOf('subject'), iFrom = H.indexOf('fromEmail'), iSend = H.indexOf('senderEmail');
  if (iTs >= 0) {
    for (let k = 1; k < values.length && !found; k++) {
      const r = values[k] || [];
      if (secs(r[iTs]) !== mine) continue;
      if (iSub >= 0 && subj(r[iSub]) !== mySubject) continue;
      const rowSender = addr(iFrom >= 0 ? r[iFrom] : '') || addr(iSend >= 0 ? r[iSend] : '');
      if (rowSender && mySender && rowSender !== mySender) continue;
      found = true;
    }
  }
}
return [{
  json: { ...original.json, _alreadyLogged: found },
  binary: original.binary
}];

// One item per attachment. file_size = the real byte size of the attachment: together with the file
// name it identifies a file, so a generic name such as 'image.png' (different pictures in different
// emails) is not mistaken for a file that is already in Drive, while the same file attached again
// is recognised and reused instead of being uploaded once more.
const items = $input.all();
const newItems = [];

for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
  const item = items[itemIndex];
  const jsonData = item.json || {};
  const binaries = item.binary || {};

  let index = 0;
  for (const key in binaries) {
    // Get the original filename if available
    const originalFileName = binaries[key].fileName || key;
    const binaryKey = `attachment_${index}`;

    let fileSize = null;
    try {
      fileSize = (await this.helpers.getBinaryDataBuffer(itemIndex, key)).length;
    } catch (e) {
      fileSize = null; // unknown size: the lookup then falls back to the file name alone
    }

    newItems.push({
      json: {
        ...jsonData,
        file_name: originalFileName,
        binary_field_name: binaryKey, // <-- added field name of binary
        file_size: fileSize
      },
      binary: {
        [binaryKey]: binaries[key]
      },
      // keeps the lineage back to the source email for every downstream $('Node').item lookup
      pairedItem: itemIndex
    });
    index++;
  }
}

return newItems;

// One request per attachment goes into the exact-name lookup above, so 'results' has exactly one item
// per attachment, in the same order, each {files: [...]} with the files of this attachments folder
// whose name is EXACTLY the attachment's file name (oldest first). The old lookup was a fuzzy
// Drive 'name contains' search capped at 5 results, which missed file names such as
// Bathtub_26DDYP43_1.jpg -- so the same photo was uploaded again on every run.
// A file counts as already uploaded when name AND byte size match (size unknown -> name only).
// Preserve the ORIGINAL item's json (file_name, binary_field_name, ...) and binary data untouched,
// just annotated with the match result -- 'Drive | Upload Attachment' needs them to upload.
const originals = $('Expand | Split Attachments').all();
const results = $input.all();

return originals.map((orig, idx) => {
  const expected = (orig.json.file_name || '').toString().trim().toLowerCase();
  const size = orig.json.file_size;
  const files = results[idx]?.json?.files || [];
  const exact = files.find(f =>
    (f.name || '').toString().trim().toLowerCase() === expected &&
    (size === null || size === undefined || f.size === undefined || String(f.size) === String(size)));
  return {
    json: {
      ...orig.json,
      _existingFileId: exact ? exact.id : '',
      _existingFileWebViewLink: exact ? (exact.webViewLink || '') : ''
    },
    binary: orig.binary,
    pairedItem: idx
  };
});

// 'Pick Exact Attachment Match' only sets _existingFileWebViewLink from
// the Drive search result's own webViewLink -- that search response isn't
// guaranteed to include it either, so fall back to the same canonical
// Drive URL format built from the file id it always does return.
return $input.all().map(item => ({
  json: {
    webViewLink: item.json._existingFileWebViewLink
      || (item.json._existingFileId ? `https://drive.google.com/file/d/${item.json._existingFileId}/view?usp=drivesdk` : null)
  },
  pairedItem: item.pairedItem
}));

// Get previous node data -- drop tabName, it's routing metadata (which
// tab of the conversation sheet to write to) used by upstream/downstream
// nodes, not a column that belongs in the sheet itself.
const { tabName, ...previousData } = $('Message Already Logged?').item.json;

// When a message has no attachments, 'If Has Attachments'' false branch
// feeds this node the single ORIGINAL message item untouched -- NOT a
// Drive file result. That item's own `id` is the Outlook message id
// (e.g. 'AAMkADEzYjVk...'), so treating it as a fallback Drive file id
// synthesized a bogus drive.google.com link on every attachment-less row.
// Only ever read $input as Drive results when this message actually went
// through the attachment branch.
//
// 'Drive | Upload Attachment' has no explicit `fields` option, so its
// response isn't guaranteed to include webViewLink -- only `id` is
// guaranteed on any real Drive file response. Rebuild the same canonical
// URL Drive itself uses (confirmed identical to what the search path
// already returns) from the id whenever webViewLink itself didn't come
// back, instead of silently saving a blank link for a file that really is
// sitting in Drive.
const links = previousData.hasAttachments
  ? $input.all()
      .map(item => item.json.webViewLink
        || (item.json.id ? `https://drive.google.com/file/d/${item.json.id}/view?usp=drivesdk` : null))
      .filter(link => !!link)
  : [];

// Collect all webViewLinks -- named 'webViewLink1'/'webViewLink2'/... to
// match the conversation sheet's actual existing header columns. A prior
// version of this named them 'attachment1'/'attachment2', which didn't
// match any existing header, so autoMapInputData created a brand new
// 'attachment1' column instead of populating the real webViewLink1/2
// columns every other row (Gmail included) already uses.
const linkFields = {};
links.forEach((link, index) => {
  linkFields[`webViewLink${index + 1}`] = link;
});

return [
  {
    json: {
      ...previousData,
      ...linkFields
    }
  }
];

// Memory guard: each run handles at most MAX_ROWS waiting queue rows. A run that loads thousands of rows and keeps every message
// (and its attachments) in memory is stopped by n8n without an error. Start the workflow again for the next rows; rows already
// processed are marked TRUE and skipped. Change MAX_ROWS to make runs shorter or longer.
const MAX_ROWS = 150;
return $input.all().slice(0, MAX_ROWS);
